import{_ as a,o as s,c as e,a3 as d}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"参数系统","description":"","frontmatter":{},"headers":[],"relativePath":"features/params.md","filePath":"features/params.md","lastUpdated":1791133906000}'),n={name:"features/params.md"};function o(r,t,i,l,h,p){return s(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="参数系统" tabindex="-1">参数系统 <a class="header-anchor" href="#参数系统" aria-label="Permalink to &quot;参数系统&quot;">​</a></h1><p>框架的核心是<strong>参数系统</strong>：把游戏内散落各处的数值，统一成一张「参数表」，让你能集中查看和调节。</p><h2 id="为什么用「倍率」而不是「数值」" tabindex="-1">为什么用「倍率」而不是「数值」 <a class="header-anchor" href="#为什么用「倍率」而不是「数值」" aria-label="Permalink to &quot;为什么用「倍率」而不是「数值」&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">关键设计</p><p>参数改的不是「伤害 = 100」，而是「伤害 = 原值 × 1.5」。</p><p>这样设计的好处：<strong>原版游戏的平衡不会被破坏</strong>。不同舰船、不同武器的原始伤害差异全部保留，你只是整体放大或缩小。而且原版更新后，参数不会失效。</p></div><p>举个例子：原版主炮伤害 10，重巡洋舰 20。你把 <code>gun.damageMul</code> 调到 1.5 之后：</p><table tabindex="0"><thead><tr><th></th><th>原版</th><th>调到 1.5 后</th></tr></thead><tbody><tr><td>驱逐舰主炮</td><td>10</td><td>15</td></tr><tr><td>重巡主炮</td><td>20</td><td>30</td></tr></tbody></table><p><strong>两者的相对差异（2 倍）保持不变。</strong></p><h2 id="参数的三个属性" tabindex="-1">参数的三个属性 <a class="header-anchor" href="#参数的三个属性" aria-label="Permalink to &quot;参数的三个属性&quot;">​</a></h2><p>每个参数都有三个值，理解它们很重要：</p><table tabindex="0"><thead><tr><th>属性</th><th>含义</th><th>你的感受</th></tr></thead><tbody><tr><td><strong>默认值</strong></td><td>框架认为的「原版值」</td><td>通常是 <code>1.0</code>（倍率）或 <code>0</code>（开关）</td></tr><tr><td><strong>软边界</strong></td><td>滑块的<strong>推荐范围</strong></td><td>拖到底就是这里，日常在这里调</td></tr><tr><td><strong>硬边界</strong></td><td>框架接受的<strong>绝对上限/下限</strong></td><td>手写 mod.json 时超过这个会被<strong>静默截断</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">硬边界是「静默」的</p><p>如果你手写 mod.json 里填了 <code>gun.damageMul: 99</code>，而硬边界是 <code>5</code>，框架<strong>不会报错</strong>，会直接把它当成 <code>5</code>。</p><p>这很容易造成「我明明写了 99 却没效果」的困惑。所以：</p><ul><li>面板上拖滑块 → 永远不会超边界（滑块本身就在范围内）</li><li>手写 mod.json → 注意对照 <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a> 的硬边界列</li></ul></div><h2 id="怎么调" tabindex="-1">怎么调 <a class="header-anchor" href="#怎么调" aria-label="Permalink to &quot;怎么调&quot;">​</a></h2><p>三种方式，从易到难：</p><h3 id="方式一-面板拖滑块-推荐" tabindex="-1">方式一：面板拖滑块（推荐） <a class="header-anchor" href="#方式一-面板拖滑块-推荐" aria-label="Permalink to &quot;方式一：面板拖滑块（推荐）&quot;">​</a></h3><p>「参数」页 → 找到分组 → 拖滑块。倍率类默认 <code>1.0</code>，往右是增强。</p><h3 id="方式二-一键预设" tabindex="-1">方式二：一键预设 <a class="header-anchor" href="#方式二-一键预设" aria-label="Permalink to &quot;方式二：一键预设&quot;">​</a></h3><p>面板上某些参数提供<strong>一键设值</strong>按钮（如「开局威望」有 10 万 / 50 万 / 100 万档次），省得拖。</p><h3 id="方式三-手写-mod-json" tabindex="-1">方式三：手写 mod.json <a class="header-anchor" href="#方式三-手写-mod-json" aria-label="Permalink to &quot;方式三：手写 mod.json&quot;">​</a></h3><p>适合做成 Mod 分享给别人：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;modName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;强化主炮&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;combat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;gun&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;damageMul&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;accuracyMul&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="参数的分组" tabindex="-1">参数的分组 <a class="header-anchor" href="#参数的分组" aria-label="Permalink to &quot;参数的分组&quot;">​</a></h2><p>23 个参数按功能分组成几大类，对应面板上的分组：</p><table tabindex="0"><thead><tr><th>分组</th><th>参数前缀</th><th>说明</th></tr></thead><tbody><tr><td>战斗</td><td><code>gun.</code> <code>torpedo.</code> <code>bomb.</code> <code>dc.</code> <code>hedgehog.</code></td><td>各类武器的伤害与命中</td></tr><tr><td>环境</td><td><code>wind.</code></td><td>风对炮弹的影响</td></tr><tr><td>感知</td><td><code>sensor.</code></td><td>声呐、雷达范围</td></tr><tr><td>航空</td><td><code>air.</code></td><td>舰载机规模</td></tr><tr><td>经济</td><td><code>economy.</code> <code>repair.</code></td><td>威望收入、修理时间</td></tr><tr><td>AI</td><td><code>ai.</code></td><td>敌方反应速度</td></tr><tr><td>沙盒</td><td><code>sandbox.</code> <code>unlock.</code></td><td>调试开关</td></tr><tr><td>联机</td><td><code>local.</code></td><td>本地热座</td></tr><tr><td>调试</td><td><code>debug.</code></td><td>日志开关</td></tr></tbody></table><h2 id="完整参数清单" tabindex="-1">完整参数清单 <a class="header-anchor" href="#完整参数清单" aria-label="Permalink to &quot;完整参数清单&quot;">​</a></h2><p>23 个参数的<strong>键名 / 默认值 / 软边界 / 硬边界 / 中文说明</strong>全表，见 <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a>。这是<strong>权威对照表</strong>，手写 mod.json 时以它为准。</p><h2 id="改了之后怎么生效" tabindex="-1">改了之后怎么生效 <a class="header-anchor" href="#改了之后怎么生效" aria-label="Permalink to &quot;改了之后怎么生效&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">必须重开游戏</p><p>参数在<strong>游戏启动时读取一次</strong>。运行中修改不会即时生效。</p><p>流程：改 → 完全退出游戏 → 重开 → 生效。</p></div><h2 id="怎么知道当前改了哪些" tabindex="-1">怎么知道当前改了哪些 <a class="header-anchor" href="#怎么知道当前改了哪些" aria-label="Permalink to &quot;怎么知道当前改了哪些&quot;">​</a></h2><p>面板 → 「<strong>状态</strong>」页，会列出<strong>所有当前值 ≠ 默认值的参数</strong>。</p><p>这是排查问题最快的地方。任何时候觉得「数值怎么不对劲」，先来这里看。</p><h2 id="怎么全部还原" tabindex="-1">怎么全部还原 <a class="header-anchor" href="#怎么全部还原" aria-label="Permalink to &quot;怎么全部还原&quot;">​</a></h2><p>「参数」页 → 「<strong>恢复默认</strong>」（两段确认）。</p><p>这个操作会把<strong>所有</strong>参数清空回默认值，但你装的 Mod 不会被删（Mod 里的配置在下次启动时又会生效 —— 想彻底停用要去「Mod」页禁用）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>具体能调什么 → <a href="/AtlanticFleetSite/docs/features/combat">战斗数值</a> / <a href="/AtlanticFleetSite/docs/features/economy">经济与威望</a> / …</li><li>完整键名表 → <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a></li><li>在面板上怎么操作 → <a href="/AtlanticFleetSite/docs/use/params-page">参数页：调数值</a></li></ul>`,35)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
